import * as THREE from 'three/webgpu';
import { texture, uv, vec4, mix, positionLocal } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-card-1-label';

  const width = 1.6;
  const height = (320 / 512) * width;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const surfaceColor = new THREE.Color(0x0b0b10);
  const inkColor = new THREE.Color(0x16161d);

  const texNode = texture(map, uv());
  const gradientNode = mix(vec4(surfaceColor, 1.0), vec4(inkColor, 1.0), uv().y);
  material.colorNode = mix(gradientNode, texNode, 0.55);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'collection-card-1-label-plane';
  group.add(mesh);

  const textMesh = ctx.fontAtlas.createText({
    text: 'Collection 2',
    font: 'display',
    weight: 400,
    size: 0.34,
    color: '#e8ecf2',
    atlasIndex: 0,
    sourceRect: [0, 0, 512, 320],
    align: 'center',
    anchor: 'center'
  });
  textMesh.name = 'collection-card-1-label-text';
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
  };

  return group;
}
